<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\AuditLog;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\Rule;
class AdminAccessController extends Controller{public const PERMISSIONS=['dashboard','orders','catalog','moderation','finance','marketing','support','system'];public function admins(){return view('admin.access.admins',['admins'=>User::where('role','admin')->latest()->get(),'permissions'=>self::PERMISSIONS]);}public function store(Request $r){$d=$r->validate(['name'=>['required','string','max:120'],'email'=>['required','email','unique:users,email'],'password'=>['required','string','min:8'],'admin_role'=>['required',Rule::in(['super_admin','order_manager','content_manager','moderator','support','accountant','marketer'])],'permissions'=>['nullable','array'],'permissions.*'=>[Rule::in(self::PERMISSIONS)]]);$d['password']=Hash::make($d['password']);$d['role']='admin';$d['admin_permissions']=$d['admin_role']==='super_admin'?self::PERMISSIONS:($d['permissions']??[]);unset($d['permissions']);User::create($d);return back()->with('status','Администратор создан.');}public function update(Request $r,User $admin){abort_unless($admin->isAdmin(),404);abort_if($admin->id===$r->user()->id&&$r->input('admin_role')!=='super_admin',422,'Нельзя понизить собственную роль.');$d=$r->validate(['admin_role'=>['required',Rule::in(['super_admin','order_manager','content_manager','moderator','support','accountant','marketer'])],'permissions'=>['nullable','array'],'permissions.*'=>[Rule::in(self::PERMISSIONS)]]);$admin->update(['admin_role'=>$d['admin_role'],'admin_permissions'=>$d['admin_role']==='super_admin'?self::PERMISSIONS:($d['permissions']??[])]);return back()->with('status','Права обновлены.');}public function audit(Request $r){$logs=AuditLog::with('user')->when($r->filled('user_id'),fn($q)=>$q->where('user_id',$r->integer('user_id')))->latest()->paginate(30)->withQueryString();return view('admin.access.audit',compact('logs'));}}
